import{_ as s,o as t,c as n,a4 as e}from"./chunks/framework.BMj-uaUw.js";const g=JSON.parse('{"title":"单元 1 · AI 协作：用 AI 做调研和排错，结论得自己核","description":"","frontmatter":{},"headers":[{"level":2,"title":"这一章哪些活能交给 AI","slug":"这一章哪些活能交给-ai","link":"#这一章哪些活能交给-ai","children":[]},{"level":2,"title":"提示词怎么写","slug":"提示词怎么写","link":"#提示词怎么写","children":[{"level":3,"title":"1. 让它把概念讲成人话","slug":"_1-让它把概念讲成人话","link":"#_1-让它把概念讲成人话","children":[]},{"level":3,"title":"2. 让它帮你读报错","slug":"_2-让它帮你读报错","link":"#_2-让它帮你读报错","children":[]},{"level":3,"title":"3. 让它列环境清单","slug":"_3-让它列环境清单","link":"#_3-让它列环境清单","children":[]}]},{"level":2,"title":"AI 在这一章容易错什么","slug":"ai-在这一章容易错什么","link":"#ai-在这一章容易错什么","children":[{"level":3,"title":"编造一个不存在的包名或命令","slug":"编造一个不存在的包名或命令","link":"#编造一个不存在的包名或命令","children":[]},{"level":3,"title":"给一个过时的安装方式","slug":"给一个过时的安装方式","link":"#给一个过时的安装方式","children":[]},{"level":3,"title":"按主流环境给你答案，忽略你的实际情况","slug":"按主流环境给你答案-忽略你的实际情况","link":"#按主流环境给你答案-忽略你的实际情况","children":[]}]},{"level":2,"title":"怎么验收 AI 的产出","slug":"怎么验收-ai-的产出","link":"#怎么验收-ai-的产出","children":[]},{"level":2,"title":"练习","slug":"练习","link":"#练习","children":[{"level":3,"title":"用 AI 把一份报错查清楚","slug":"用-ai-把一份报错查清楚","link":"#用-ai-把一份报错查清楚","children":[]}]}],"relativePath":"unit01/ai-collaboration.md","filePath":"unit01/ai-collaboration.md","lastUpdated":1789356894000}'),i={name:"unit01/ai-collaboration.md"};function l(o,a,p,r,d,c){return t(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="单元-1-·-ai-协作-用-ai-做调研和排错-结论得自己核" tabindex="-1">单元 1 · AI 协作：用 AI 做调研和排错，结论得自己核 <a class="header-anchor" href="#单元-1-·-ai-协作-用-ai-做调研和排错-结论得自己核" aria-label="Permalink to &quot;单元 1 · AI 协作：用 AI 做调研和排错，结论得自己核&quot;">​</a></h1><p>这一章你还没开始写业务代码，AI 在这里的用处不是“帮你写”，是<strong>帮你把看不懂的东西看懂，把找不到的线索找出来</strong>。</p><p>但这一章也是 AI 最容易把你带偏的地方：它给的命令、包名、版本号，都可能是不存在的。</p><h2 id="这一章哪些活能交给-ai" tabindex="-1">这一章哪些活能交给 AI <a class="header-anchor" href="#这一章哪些活能交给-ai" aria-label="Permalink to &quot;这一章哪些活能交给 AI&quot;">​</a></h2><p>判断标准先立起来：<strong>能让你更快理解一件事的活可以交，需要你自己做判断的活不能交。</strong></p><table tabindex="0"><thead><tr><th>任务</th><th>能交给 AI 吗</th><th>为什么</th></tr></thead><tbody><tr><td>解释一个陌生概念</td><td>可以</td><td>它见过的解释比教程多，换个说法往往就通了</td></tr><tr><td>把报错信息翻译成人话</td><td>可以</td><td>报错原文是给工具看的，不是给人看的</td></tr><tr><td>根据你的情况列环境自检清单</td><td>可以</td><td>它知道一个前端工程通常要装什么</td></tr><tr><td>对比两个工具的区别</td><td>可以</td><td>能快速给你一张对比表当起点</td></tr><tr><td>判断你该先学什么、走哪个方向</td><td><strong>不行</strong></td><td>它不了解你的基础、时间、目标，这是你要自己定的</td></tr><tr><td>给出安装命令和版本号</td><td><strong>不能直接信</strong></td><td>后面的“容易错什么”专讲这一节</td></tr><tr><td>决定你的目录结构</td><td><strong>不行</strong></td><td>取决于你的项目实际，它看不到</td></tr></tbody></table><p>最后三行是这一章的重点。<strong>AI 在这一章的作用是“把信息整理清楚”，不是“替你做决定”。</strong></p><h2 id="提示词怎么写" tabindex="-1">提示词怎么写 <a class="header-anchor" href="#提示词怎么写" aria-label="Permalink to &quot;提示词怎么写&quot;">​</a></h2><h3 id="_1-让它把概念讲成人话" tabindex="-1">1. 让它把概念讲成人话 <a class="header-anchor" href="#_1-让它把概念讲成人话" aria-label="Permalink to &quot;1. 让它把概念讲成人话&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用一句话解释 [概念] 是什么、解决什么问题、什么时候不该用。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>然后举一个校园活动管理后台里的例子，说明如果没有它会遇到什么麻烦。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要展开讲原理，我要的是判断标准。</span></span></code></pre></div><p><strong>为什么这么写</strong>：“一句话”是硬约束，能挡掉长篇大论。要求用<strong>你自己的项目</strong>举例，是因为泛泛的例子你看了不会往心里去 —— 换成活动管理后台的场景，你立刻能对上号。最后一句防的是它一上来就讲实现细节。</p><h3 id="_2-让它帮你读报错" tabindex="-1">2. 让它帮你读报错 <a class="header-anchor" href="#_2-让它帮你读报错" aria-label="Permalink to &quot;2. 让它帮你读报错&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我在装环境时遇到这个报错：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[完整粘贴报错，不要只贴一句]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>我的系统是 [Windows 11 / macOS 15]，用的是 [Node 24 LTS]，</span></span>
<span class="line"><span>在此之前我执行的操作是 [装 fnm 并切换版本]。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请回答：</span></span>
<span class="line"><span>1. 这个报错最可能的原因是什么，按可能性排序</span></span>
<span class="line"><span>2. 为了确定是哪一种，我下一步该跑什么命令、看什么</span></span>
<span class="line"><span>3. 每种原因的解决步骤</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你确定的地方直接说结论，不确定的地方明确说不确定。</span></span></code></pre></div><p><strong>为什么这么写</strong>：报错排查最耗时间的不是“不知道原因”，是“不知道下一步看什么”。第 2 点逼它给出可执行的下一步，而不是笼统的“建议重装”。最后一句很关键 —— 让它敢说“不确定”，比拿到一个语气笃定但其实错了的答案强得多。</p><h3 id="_3-让它列环境清单" tabindex="-1">3. 让它列环境清单 <a class="header-anchor" href="#_3-让它列环境清单" aria-label="Permalink to &quot;3. 让它列环境清单&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我是软件工程技术专业的学生，要在一台 [Windows 11] 电脑上搭前端开发环境，</span></span>
<span class="line"><span>之后要学 Vue 3、用 Vite 构建、用 Git 提交代码。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请列一份环境自检清单：每项要装什么、怎么确认装好了、装错会有什么表现。</span></span>
<span class="line"><span>用表格，三列。</span></span></code></pre></div><p><strong>为什么这么写</strong>：把“你要干什么”讲清楚，清单才不会是通用的。要求给“装错的表现”，是因为环境问题最难的地方就是<strong>装错了但不报错</strong> —— 比如 Node 装了但 PATH 没配好。</p><h2 id="ai-在这一章容易错什么" tabindex="-1">AI 在这一章容易错什么 <a class="header-anchor" href="#ai-在这一章容易错什么" aria-label="Permalink to &quot;AI 在这一章容易错什么&quot;">​</a></h2><h3 id="编造一个不存在的包名或命令" tabindex="-1">编造一个不存在的包名或命令 <a class="header-anchor" href="#编造一个不存在的包名或命令" aria-label="Permalink to &quot;编造一个不存在的包名或命令&quot;">​</a></h3><p><strong>现象</strong>：它给你的安装命令里有个包名，格式完全正常，看起来很像真的，但装的时候报 <code>404 Not Found</code> 或 <code>package not found</code>。</p><p><strong>原因</strong>：它并不是“查了官方仓库发现没有”，而是根据见过的成百上千个包名，按命名规则拼了一个出来。这种行为有个名字叫“幻觉依赖”。同一个问题也会出现在命令上 —— 比如让你执行某个工具里并不存在的子命令。</p><p><strong>怎么处理</strong>：装之前先确认存在。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查 npm 上的包是否存在、最新版本是多少</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.npmjs.org/vue/latest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 包名里带斜杠的，斜杠要转义成 %2F</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.npmjs.org/@vue%2Fuse%2Fcore/latest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span></span></code></pre></div><p>返回 <code>{&quot;error&quot;:&quot;Not found&quot;}</code> 就是不存在。命令的话，用 <code>command -v 命令名</code> 看有没有。</p><h3 id="给一个过时的安装方式" tabindex="-1">给一个过时的安装方式 <a class="header-anchor" href="#给一个过时的安装方式" aria-label="Permalink to &quot;给一个过时的安装方式&quot;">​</a></h3><p><strong>现象</strong>：它让你 <code>npm install -g</code> 全局装某个工具，或者让你用一个已经废弃的工具。</p><p><strong>原因</strong>：它的知识有截止时间，而前端工具链的推荐做法两三年就会换一轮。比如包管理器从全局安装转向了版本管理工具，很多老教程里的做法现在已经不推荐。</p><p><strong>怎么处理</strong>：安装方式以<strong>官方文档</strong>为准。判断方法很简单：搜一下工具名加“官方文档”，看首页的 Getting Started 里写的是什么。另外，看到 <code>-g</code> 要警惕 —— 全局安装的包会污染系统环境，不利于版本切换，现在的推荐做法基本都不用全局安装。</p><h3 id="按主流环境给你答案-忽略你的实际情况" tabindex="-1">按主流环境给你答案，忽略你的实际情况 <a class="header-anchor" href="#按主流环境给你答案-忽略你的实际情况" aria-label="Permalink to &quot;按主流环境给你答案，忽略你的实际情况&quot;">​</a></h3><p><strong>现象</strong>：你在 Windows 上，它给的命令是 macOS 的；或者反过来。</p><p><strong>原因</strong>：它默认按训练数据里出现最多的环境回答。你的系统、Shell、已有版本这些信息，它不看你的电脑是不知道的。</p><p><strong>怎么处理</strong>：<strong>每次提问都把环境说清楚。</strong> 一句话的事：<code>我的系统是 Windows 11，用 PowerShell</code>。上面第 2 个提示词模板里特意留了系统这一项，就是为了这个。</p><details class="details custom-block"><summary>还有一类错误：把“能跑”说成“没问题”</summary><p><strong>现象</strong>：你问“这个配置对不对”，它回答“配置正确，可以正常使用”。你按它说的做了，结果启动不起来。</p><p><strong>原因</strong>：它没有运行环境，无法真正验证。它判断“对不对”的依据是这段配置看起来符不符合规范。</p><p><strong>怎么处理</strong>：把问题从“对不对”改成“怎么验证”。例如不要问“我这个 PATH 配得对吗”，改问“我该怎么确认 PATH 配好了，给我一条能直接跑的命令”。<strong>能跑的验证命令比“应该没问题”可靠得多。</strong></p></details><h2 id="怎么验收-ai-的产出" tabindex="-1">怎么验收 AI 的产出 <a class="header-anchor" href="#怎么验收-ai-的产出" aria-label="Permalink to &quot;怎么验收 AI 的产出&quot;">​</a></h2><p>这一章的产出大多是<strong>信息</strong>，不是代码，所以验收动作也不一样。逐条过：</p><ul><li>[ ] 它给的每一个包名，都在 <code>registry.npmjs.org</code> 上查到了</li><li>[ ] 它给的每一个命令，都用 <code>command -v</code> 或官方文档确认过存在</li><li>[ ] 它给的每个版本号，都在官方渠道核实过（npm registry 或 nodejs.org）</li><li>[ ] 安装方式与官方文档的 Getting Started 一致，没有出现 <code>-g</code></li><li>[ ] 提问时说明了你的操作系统和 Shell，它的回答没有假设错环境</li><li>[ ] 问到“对不对”时，它给的是可执行的验证命令，而不是“应该没问题”</li><li>[ ] 你不能确定的地方，已经动手试过一遍，而不是直接写进环境自检报告</li></ul><p>前四条对应“信息真不真”，中间一条对应“针不针对我”，最后两条对应“有没有真的验证”。<strong>这七条过完，AI 在这一章的产出就可以用了。</strong></p><h2 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to &quot;练习&quot;">​</a></h2><h3 id="用-ai-把一份报错查清楚" tabindex="-1">用 AI 把一份报错查清楚 <a class="header-anchor" href="#用-ai-把一份报错查清楚" aria-label="Permalink to &quot;用 AI 把一份报错查清楚&quot;">​</a></h3><p><strong>任务</strong>：故意制造一个环境报错，然后用 AI 把它查清楚，写成一份记录。</p><p>制造报错的几个办法（挑一个）：</p><ol><li>故意把 <code>package.json</code> 里的 <code>&quot;type&quot;: &quot;module&quot;</code> 删掉，再运行 <code>pnpm dev</code>。</li><li>故意写一个不存在的依赖名，执行 <code>pnpm install</code>。</li><li>把 Node 版本切到一个很老的版本，再跑一个新项目。</li></ol><p><strong>要求</strong>：记录里必须包含这四项，顺序不能变：</p><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>报错原文</td><td>完整粘贴，不许删减，不许只写“报错了”</td></tr><tr><td>AI 的第一版回答</td><td>按可能性排序的原因列表</td></tr><tr><td>你实际验证的结果</td><td>哪些原因被排除、用什么命令排除的</td></tr><tr><td>最终原因与解决</td><td>现象 → 原因 → 解决 → 怎么预防下次</td></tr></tbody></table><details class="details custom-block"><summary>验收标准与参考思路</summary><p><strong>为什么要“故意制造报错”</strong>：等报错自己找上门，你只会手忙脚乱地试；主动造一个，你才有余力观察是哪一环出的问题。而且你知道正确答案，正好能验证 AI 说得对不对。</p><p><strong>思路提示</strong>：</p><ul><li>提问时一定要贴<strong>完整报错</strong>，尤其别删掉最后那几行 —— 真正的原因往往在最后一行。</li><li>让 AI 给出“下一步该看什么”，然后你真的去看。这一步是重点，别跳过。</li><li>如果 AI 的第一版原因猜错了，<strong>把它猜错的这一条也记下来</strong>，写清你是怎么排除的。这类记录在后续单元会一直用。</li><li>环境类报错的排查顺序可以从这里切入：先确认命令本身存在 → 再确认 Node 版本对得上 → 再确认依赖装上了 → 最后才怀疑代码。</li></ul><p><strong>不合格的写法</strong>：</p><blockquote><p>AI 说是 Node 版本问题，我换了版本就好了。</p></blockquote><p>这句话没有信息量：换到什么版本？为什么原版本不行？怎么确认就是版本问题而不是碰巧好了？</p><p><strong>合格的写法</strong>：</p><blockquote><p>报错是 <code>SyntaxError: Unexpected token &#39;export&#39;</code>。AI 给了三个原因，第一个是 <code>package.json</code> 里缺 <code>&quot;type&quot;: &quot;module&quot;</code>。 我用 <code>node -e &quot;console.log(require(&#39;./package.json&#39;).type)&quot;</code> 查到返回 <code>undefined</code>，确认了这一条。 补上 <code>&quot;type&quot;: &quot;module&quot;</code> 后报错消失。原因是 Node 默认把 <code>.js</code> 当 CommonJS 处理， 而 Vite 的配置文件用的是 ESM 语法。预防办法：以后新建工程先确认这三个字段 —— <code>type</code>、<code>engines</code>、<code>packageManager</code>。</p></blockquote><p>差别在于：后者<strong>能复现、能验证、能迁移到别的场景</strong>。</p></details><hr><p>上一节：<a href="/frontend-engineering-course/unit01/04-environment.html">1.4 开发环境搭建与自检</a> · 课后练习：<a href="/frontend-engineering-course/unit01/practice.html">单元 1 课后练习</a></p>`,47)])])}const u=s(i,[["render",l]]);export{g as __pageData,u as default};
